local pi = 180
local function easeInSine(x)
    return 1 - cos(x * pi / 2)
end
local function easeOutSine(x)
    return sin(x * pi / 2);
end
local function easeInOutSine(x)
    return (1 - cos(x * pi)) / 2;
end
