_editor_class["LHX_144th_nsc_obj1"]=Class(_object)
_editor_class["LHX_144th_nsc_obj1"].init=function(self,_x,_y,x0,y0,x1,y1,inia,omega,accrot)
    self.x,self.y=_x,_y
    self.img="parimg5"
    self.layer=LAYER_ENEMY_BULLET
    self.group=GROUP_INDES
    self.hide=false
    self.bound=false
    self.navi=false
    self.hp=10
    self.maxhp=10
    self.colli=false
    self._servants={}
    self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    self.rot = 45
    _object.set_color(self,"mul+add",255,255,122,0)
    lasttask=task.New(self,function()
        lasttask=task.New(self,function()
            for _=1,120 do
                last=New(_editor_class["LHX_144th_nsc_particle"],self.x,self.y,ran:Float(0,360),ran:Float(0.5,1))
                task._Wait(1)
            end
        end)
        task.BezierMoveTo(90,MODE_NORMAL,x0,y0,x1,y1)
        PlaySound("kira01",0.1,self.x/256,false)
        do
            local _beg_sc=1.2 local sc=_beg_sc local _end_sc=0 local _w_sc=0 local _d_w_sc=1/(15-1)
            for _=1,15 do
                self.hscale = sc self.vscale = sc
                task._Wait(1)
                _w_sc=_w_sc+_d_w_sc sc=(_beg_sc-_end_sc)*(_w_sc-1)^2+_end_sc
            end
        end
        PlaySound("tan00",0.1,self.x/256,false)
        local pre = nil local first = nil local cur = nil self.rad = 0
        do
            local a0=inia local _d_a0=(90)
            for _=1,4 do
                do
                    local _beg_a1=0 local a1=_beg_a1 local _end_a1=90 local _d_a1=(_end_a1-_beg_a1)/(12)
                    local i=0 local _d_i=(1)
                    local _h_g=(80-(0))/2 local _t_g=(80+(0))/2 local g=_h_g*sin(-90)+_t_g local _w_g=-90 local _d_w_g=1*360/(12)
                    for _=1,12 do
                        last=New(_editor_class["LHX_144th_nsc1_bullet1"],self.x,self.y,self, a0+a1, 1/cos(45-a1), omega, g)
                        if a0 == inia and a1 == 0 then self.s = last end
                        if a1 == 0 then
                            cur = last
                            if pre then
                                last=New(_editor_class["LHX_144th_laser"],self.x,self.y,pre,cur)
                            else
                                if a1 == 0 then first = last end
                            end
                            pre = cur
                        end
                        if i%2 == 0 then
                            do
                                local _beg_a2=-0.5 local a2=_beg_a2 local _end_a2=0.5 local _d_a2=(_end_a2-_beg_a2)/(3-1)
                                local _h_dv=(0.2-(0))/2 local _t_dv=(0.2+(0))/2 local dv=_h_dv*sin(-90)+_t_dv local _w_dv=-90 local _d_w_dv=1*360/(3-1)
                                for _=1,3 do
                                    last=New(_straight,square,COLOR_BLUE,self.x,self.y,dv,a0+a1+a2,false,0,true,true,0,false,0,0,0,false)
                                    do
                                        local self = last
                                        local rate = 1/cos(45-a1)
                                        do
                                            local __terminated = false
                                            local __terminateCount = 0
                                            local _0 = self._speed
                                            task.New(self, function()
                                                local self = task.GetSelf()
                                                task.Wait(0)
                                                local i = 0
                                                local offset = 0
                                                local curr, ibeg, ky, kx
                                                local prev = self._speed
                                                local target = offset
                                                curr = self._speed
                                                ibeg = i
                                                target = 0 + offset
                                                kx = target - ibeg
                                                ky = curr - prev
                                                while i < target do
                                                    _0 = prev + ky * (i - ibeg) / kx
                                                    i = i + 1
                                                    task.Wait()
                                                end
                                                _0 = curr
                                                prev = curr
                                                curr = rate
                                                ibeg = i
                                                target = 60 + offset
                                                kx = target - ibeg
                                                ky = curr - prev
                                                while i < target do
                                                    _0 = prev + ky * easeInSine((i - ibeg) / kx)
                                                    i = i + 1
                                                    task.Wait()
                                                end
                                                _0 = curr
                                                prev = curr
                                                offset = target
                                                __terminateCount = __terminateCount + 1
                                            end)
                                            task.New(self, function()
                                                local self = task.GetSelf()
                                                for _ = 1, _infinite do
                                                    SetV2(self, _0, self.rot, true, false)
                                                    if __terminated or __terminateCount >= 1 then break end
                                                    task.Wait()
                                                end
                                            end)
                                        end
                                    end
                                    a2=a2+_d_a2
                                    _w_dv=_w_dv+_d_w_dv dv=_h_dv*sin(_w_dv)+_t_dv
                                end
                            end
                        end
                        a1=a1+_d_a1
                        i=i+_d_i
                        _w_g=_w_g+_d_w_g g=_h_g*sin(_w_g)+_t_g
                    end
                end
                a0=a0+_d_a0
            end
        end
        last=New(_editor_class["LHX_144th_laser"],self.x,self.y,pre,first)
        self.img="img_void"        lasttask=task.New(self,function()
            task._Wait(60)
            _set_a(self,0.01,accrot,false)
            _forbid_v(self,1.4,'original','original')
            task._Wait(1200)
            self.bound = true
        end)
        lasttask=task.New(self,function()
            do
                local _beg_r=0 local r=_beg_r local _end_r=240 local _w_r=0 local _d_w_r=1/(240-1)
                for _=1,240 do
                    self.rad = r
                    task._Wait(1)
                    _w_r=_w_r+_d_w_r r=(_beg_r-_end_r)*(_w_r-1)^2+_end_r
                end
            end
        end)
        for _=1,_infinite do
            self.rot = self.s.angle + 45
            self.hscale = self.rad/8 self.vscale = self.hscale
            task._Wait(1)
        end
    end)
end
