    if IsValid(self.master) then
    	local m = self.master
    	local rate = self.rate
    	local rot = self.angle
    	self.x = m.x + m.rad * rate * cos(rot)
    	self.y = m.y + m.rad * rate * sin(rot)
    else
    	_del(self,false)
    end
end
